export function validateThaiNationalID(id: string): { valid: boolean; reason?: string } {
  const cleanId = id.replace(/\D/g, '');
  if (cleanId.length !== 13) return { valid: false, reason: 'ID must be 13 digits' };
  if (/^(\d)\1{12}$/.test(cleanId)) return { valid: false, reason: 'Repeated digits are invalid' };
  let sum = 0;
  for (let i = 0; i < 12; i++) {
    sum += parseInt(cleanId[i], 10) * (13 - i);
  }
  const checkDigit = (11 - (sum % 11)) % 10;
  const valid = checkDigit === parseInt(cleanId[12], 10);
  return { valid, reason: valid ? undefined : 'Check digit mismatch' };
}

