export function calculateSha256(data: string | Buffer): string {
  return createHash('sha256').update(data).digest('hex');
}

export class MemoryRateLimiter {
  private windows = new Map<string, { start: number; count: number }>();
  constructor(private readonly limit: number, private readonly windowMs: number) {}
  check(key: string): { allowed: boolean; remaining: number; resetMs: number } {
    const now = Date.now();
    let record = this.windows.get(key);
    if (!record || now - record.start >= this.windowMs) {
      record = { start: now, count: 0 };
      this.windows.set(key, record);
    }
    if (record.count >= this.limit) {
      return { allowed: false, remaining: 0, resetMs: this.windowMs - (now - record.start) };
    }
    record.count += 1;
    return { allowed: true, remaining: this.limit - record.count, resetMs: this.windowMs - (now - record.start) };
  }
}

