Evidence: getOrSet is not atomic. Between cache.has and cache.set another concurrent call can also miss and run factory twice, producing duplicate side effects.

Minimal fix (single-flight):
const inflight = new Map();
function getOrSet(key, factory) {
  if (cache.has(key)) return cache.get(key);
  if (inflight.has(key)) return inflight.get(key);
  const p = Promise.resolve().then(factory).finally(() => inflight.delete(key));
  inflight.set(key, p);
  return p.then(v => { cache.set(key, v); return v; });
}

