}

export function safeJsonParse(text: string): { ok: true; value: unknown } | { ok: false; error: string } {
  if (typeof text !== "string") {
    return { ok: false, error: "Input must be a string / อินพุตต้องเป็นสตริง" };
  }
  if (text.length > 1_000_000) {
    return { ok: false, error: "Payload exceeds 1MB limit / ขนาดเกิน 1MB" };
  }
  try {
    return { ok: true, value: JSON.parse(text) };
  } catch (err) {
    const msg = err instanceof Error ? err.message : "Invalid JSON";
    return { ok: false, error: `${msg} / JSON ไม่ถูกต้อง` };
  }
}

